TOOL Bash {'command': 'OUTDIR="/ssd2/lizhy_workspace/plp/trigger-free-pruning-defense-round2/result/cross_model_utility"
echo "=== FINAL RESULTS ==="
for model in mistral_phrase mistral_long trojan_llama; do
 for stage in raw def; do
 case "$model/$stage" in
 mistral_phrase/raw) log="mistral_phrase_raw.log" ;;
 mistral_phrase/def) log="util_phrase_def_adamw.log" ;;
 mistral_long/raw) log="mistral_long_raw.log" ;;
 mistral_long/def) log="util_long_def_adamw.log" ;;
 trojan_llama/raw) log="trojan_llama_raw.log" ;;
 trojan_llama/def) log="util_trojan_def_adamw.log" ;;
 esac
 echo ""
 echo "=== $model $stage ==="
 grep -E "word_perplexity|acc\b|acc_norm" "$OUTDIR/$log" 2>/dev/null | grep -v "WARNING\|is defined\|aggregation"
 done
done', 'description': 'Show all final AdamW utility results'}

